// Local development preview. Native notification/installation is never simulated.
const offline=new URLSearchParams(location.search).get('offline')==='1';
const base='https://cjluacmpanel.tail1b9e55.ts.net';
const state={page:'forum',csrf:'',account:'',query:'',days:'7',platform:'',number:1,post:0,problem:null,serial:0,category:'',sort:'latest'};
const content=document.getElementById('content'),popup=document.getElementById('popup');
let writing=false,opening=false,activeProblems=[];
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const read=key=>localStorage.getItem(key)||'';
localStorage.removeItem('acm_auto_login');
function rows(value){if(!Array.isArray(value))throw Error('数据格式异常');return value;}
const err=e=>`<div class="error" role="alert"><b>${esc(e.message||e)}</b></div>`;
const empty=text=>`<p class="empty">${esc(text)}</p>`;
const btn=(text,action)=>`<button data-action="${action}">${esc(text)}</button>`;
const card=body=>`<section class="card">${body}</section>`;
const date=seconds=>new Date(seconds*1000).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai'});
const tags=['WA','TLE','输入格式','边界','复杂度','思路','其他'];
function history(){try{return [...new Set(JSON.parse(read('acm_search_history')||'[]'))].filter(v=>typeof v==='string').slice(0,10);}catch{return [];}}
function dialog(title,html){if(popup.open)return;document.getElementById('popup-title').textContent=title;document.getElementById('popup-body').innerHTML=html;popup.showModal();math(popup);}
function math(node){node.querySelectorAll('.reader').forEach(v=>AcmReader.math(v));}
function reader(text){return `<div class="reader">${AcmReader.html(text||'')}</div>`;}
function draftKey(){return 'acm_draft_v2_'+base+'_'+(state.csrf?state.account:'guest');}
function loginPayload(username,password){return {username,password,...(/^[0-9]{4,12}$/.test(username)?{qq_id:username}:{})};}
function draft(){try{return JSON.parse(read(draftKey())||'{}');}catch{return {};}}
async function request(path,method='GET',body){
  if(offline)throw Error('离线预览：未连接后端');if(!navigator.onLine)throw Error('无网络');
  const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),15000);
  try{const response=await fetch(base+path,{method,credentials:'include',redirect:'error',signal:controller.signal,headers:{Accept:'application/json',...(body===undefined?{}:{'Content-Type':'application/json','X-CSRF-Token':state.csrf})},...(body===undefined?{}:{body:JSON.stringify(body)})});
    let data;try{data=await response.json();}catch{if(response.ok)throw Error('数据格式异常');}
    if(!response.ok){if(response.status===401)state.csrf='';throw Error(response.status===404||response.status===405?'无API接口':response.status===401?'未登录或登录已失效':response.status===403?'无访问权限':response.status>=500?'服务器异常':data?.message||'请求失败');}return data;
  }catch(e){if(e.name==='AbortError')throw Error('请求超时');if(e instanceof TypeError)throw Error(navigator.onLine?'无法连接服务器':'无网络');throw e;}finally{clearTimeout(timer);}
}
async function write(path,method,data,success){if(writing)return;writing=true;try{const result=await request(path,method,data);writing=false;await success(result);}catch(e){if(popup.open){const slot=document.getElementById('form-error');if(slot)slot.innerHTML=err(e);else{popup.close();dialog('操作失败',err(e));}}else dialog('操作失败',err(e));}finally{writing=false;}}
async function show(page=state.page){if(writing)return;if(popup.open)popup.close();state.page=page;const serial=++state.serial;content.innerHTML=empty('正在加载…');document.querySelectorAll('[data-page]').forEach(b=>b.classList.toggle('active',b.dataset.page===page));document.getElementById('global-search').disabled=!['forum','rank','problems','search'].includes(page);try{const html=await render(page);if(serial!==state.serial)return;content.innerHTML=html;bind();math(content);}catch(e){if(serial===state.serial){content.innerHTML=err(e)+'<button data-action="retry">重试</button>';bind();}}}
function needLogin(){if(!state.csrf)throw Error(offline?'离线预览：未连接后端':'未登录');}
function clubLinks(){return `<div class="stack">${[['sheets','社团题单'],['mistakes','错题本'],['reviews','待补题与间隔复习'],['templates','算法模板速查（离线）'],['checkin','训练打卡'],['training','今日训练'],['contests','赛事复盘']].map(([p,n])=>btn(n,p)).join('')}</div>`;}
function pager(total,size=20){const pages=Math.max(1,Math.ceil(total/size));return `<div class="row"><button id="prev" ${state.number<=1?'disabled':''}>上一页</button><span>第 ${state.number} / ${pages} 页</span><button id="next" ${state.number>=pages?'disabled':''}>下一页</button></div>`;}
function platformSelect(){return '<select id="platform">'+[['','全部平台'],['codeforces','Codeforces'],['luogu','洛谷'],['atcoder','AtCoder'],['nowcoder','牛客'],['cjlu','校 OJ']].map(([v,n])=>`<option value="${v}" ${v===state.platform?'selected':''}>${n}</option>`).join('')+'</select>';}
function problemButtons(row,index){return `<button data-problem-index="${index}">${esc(row.platform)} · ${esc(row.problem_id)}：讨论 / 错题 / 补题</button>`;}
async function render(page){
  if(page==='club')return '<h1>社团训练</h1>'+clubLinks();
  if(page==='forum'){let html='<h1>今天想聊点什么？</h1>'+btn('社团训练 · 题单 / 补题 / 模板 / 打卡','club')+'<div class="row"><h2>社区话题</h2><button id="filter" aria-label="筛选社区话题"><svg width="18" height="18" viewBox="0 0 24 24" aria-hidden="true"><path d="M3 4h18l-7 8v7l-4 2v-9Z" fill="none" stroke="currentColor" stroke-width="2"/></svg> 筛选</button></div>';try{const data=await request('/api/forum/posts?'+new URLSearchParams({q:state.query,category:state.category,sort:state.sort,page:state.number,page_size:12}));html+=rows(data.rows).map(v=>card(`<h3><button data-post="${v.id}">${esc(v.title)}</button></h3><p>${esc(v.excerpt)}</p><small>${esc(v.author_name)} · ${esc(v.comments_count)} 评论</small>`)).join('')+(data.total?'':empty('暂无话题'))+pager(data.total,12);}catch(e){html+=err(e);}return html;}
  if(page==='search')return '<h1>搜索当前栏目</h1>'+history().map((v,i)=>`<button data-history="${i}">${esc(v)}</button>`).join('')+btn('历史记录','history')+btn('历史记录设置','history-settings');
  if(page==='templates')return '<h1>算法模板速查</h1><p>离线 · 原创整理 · 请先阅读适用条件</p><input id="template-query" placeholder="搜索名称、标签和说明"><div id="template-list">'+templateList('')+'</div>';
  if(page==='compose'){const saved=draft();let options='<option value="">离线：分类不可用</option>';if(!offline)try{options=rows(await request('/api/forum/categories')).map(v=>`<option value="${v.id}">${esc(v.name)}</option>`).join('');}catch(e){options=`<option value="">${esc(e.message)}</option>`;}return '<h1>发布话题</h1><p>草稿仅保存在当前设备；提交由 Web 审核。</p><form id="compose"><label>分类<select name="category_id">'+options+'</select></label><label>标题<input name="title" maxlength="120" value="'+esc(saved.title||'')+'"></label><label>正文<textarea name="body" maxlength="20000">'+esc(saved.body||'')+'</textarea></label><button type="button" id="preview-body">预览</button><button '+(offline?'disabled':'')+'>提交</button></form><p id="draft-status">输入时自动保存本机草稿。</p>';}
  if(page==='account'&&!state.csrf)return '<h1>账号登录</h1><p>仅记住账号，不保存密码、不跨冷启动恢复会话。</p><form id="login"><label>用户名 / QQ<input name="username" autocomplete="username" value="'+esc(read('acm_remembered_account'))+'" required></label><label>密码<input name="password" type="password" autocomplete="off" required></label><label><input name="remember" type="checkbox" '+(read('acm_remembered_account')?'checked':'')+'>记住账号</label><button '+(offline?'disabled':'')+'>登录</button></form>';
  if(page==='detail'){const data=await request('/api/forum/posts/'+state.post);return '<h1>'+esc(data.title)+'</h1>'+reader(data.body)+btn('点赞 / 取消点赞','like')+btn('简单举报','report')+'<form id="comment"><textarea name="body" minlength="2" maxlength="5000" required></textarea><button>发布评论</button></form>'+rows(data.comments||[]).map(v=>card(`<small>${esc(v.author_name)}</small><p>${esc(v.body)}</p>`)).join('');}
  if(page!=='rank')needLogin();
  if(page==='account'||page==='mine'){const data=await request('/api/me/profile');state.profile=data;return '<h1>'+(page==='mine'?'个人中心':'账号设置')+'</h1>'+card(`<h2>${esc(data.user?.name)}</h2>`+Object.entries(data.platform_counts||{}).map(([p,n])=>`<p>${esc(p)} · ${esc(n)} 题</p>`).join('')+`<b>合计 ${esc(data.total_count)} 题</b>`)+clubLinks()+(page==='account'?'<div class="stack">'+[['rename','修改昵称'],['bindings','OJ 绑定摘要'],['recent','最近 AC'],['password','修改密码'],['compose','本地草稿'],['logout','退出登录']].map(([a,n])=>btn(n,a)).join('')+'</div><p>头像上传、本人话题等完整账号操作请在 Android App 体验；重管理操作在 Web 后台。</p>':btn('最近 AC','recent')+btn('账号设置','account'));}
  if(page==='rank'){const data=await request('/api/community/leaderboard?'+new URLSearchParams({days:state.days,platforms:state.platform,positive_only:1,search:state.query,page:state.number,page_size:20}));return '<h1>排行榜</h1><select id="days">'+[['7','周'],['30','月'],['all','总']].map(([v,n])=>`<option value="${v}" ${v===state.days?'selected':''}>${n}</option>`).join('')+'</select>'+platformSelect()+rows(data.rows).filter(v=>v.total_count>0).map((v,i)=>card(`<b>#${(state.number-1)*20+i+1} ${esc(v.name)}</b><p>${v.total_count} AC</p>`)).join('')+pager(data.total);}
  if(page==='problems'){const data=await request('/api/me/problems?'+new URLSearchParams({page:state.number,page_size:20,platform:state.platform,tag:state.query,state:state.favorite?'favorite':''}));activeProblems=rows(data.items);return '<h1>题库</h1>'+platformSelect()+btn(state.favorite?'全部题目':'只看收藏','favorites')+activeProblems.map((v,i)=>card(`<h3>${esc(v.problem_name||v.problem_id)}</h3><p>${esc(v.problem_rating??'难度未知')} · ${esc(v.tags)}</p>${problemButtons(v,i)}<button data-statement="${i}">题面 / 样例</button><button data-favorite="${i}">${v.is_favorite?'取消收藏':'收藏题目'}</button>`)).join('')+pager(data.total);}
  if(page==='sheets'){const sheets=rows(await request('/api/club/sheets'));activeProblems=[];return '<h1>社团题单</h1>'+sheets.map(sheet=>card(`<h2>${esc(sheet.title)}</h2><p>${esc(sheet.description)}</p><p>${date(sheet.deadline)} 截止（北京时间） · ${sheet.completed}/${sheet.total}</p>`+rows(sheet.items).map(v=>{const i=activeProblems.push(v)-1;return `<p>${v.completed?'✓':'○'} ${problemButtons(v,i)}</p>`;}).join(''))).join('')+(sheets.length?'':empty('暂无题单'));}
  if(page==='discussions'){if(!state.problem)throw Error('请先选择题目');const data=rows(await request('/api/club/problem-discussions?'+new URLSearchParams({...state.problem,q:state.topicQuery||'',tag:state.topicTag||''})));return '<h1>'+esc(state.problem.problem_id)+'</h1><form id="topic-filter"><input name="q" placeholder="搜索本题讨论"><select name="tag"><option value="">全部</option>'+tags.map(t=>`<option>${t}</option>`).join('')+'</select><button>查询</button></form>'+btn('发起按题讨论','new-topic')+btn('加入错题本','add-mistake')+btn('加入补题计划','add-review')+data.map(v=>card(`<h3>${esc(v.title)}</h3><p>${esc(v.tags.join(' / '))}</p><button data-post="${v.id}">评论与举报</button>${reader(v.body)}`)).join('')+(data.length?'':empty('暂无已发布讨论'));}
  if(page==='mistakes'){activeProblems=rows(await request('/api/me/club/mistakes'));return '<h1>错题本 · 仅本人可见</h1>'+activeProblems.map((v,i)=>card(problemButtons(v,i)+`<p>${esc(v.tags.join(' / '))}</p><p>${esc(v.note)}</p><button data-edit-mistake="${i}">编辑错因</button><button data-remove-mistake="${i}">移出</button>`)).join('')+(activeProblems.length?'':empty('暂无错题'));}
  if(page==='reviews'){activeProblems=rows(await request('/api/me/club/reviews'));return '<h1>补题计划</h1><p>完成复习后间隔 1、3、7 天；第四次完成结束。通知仅由 Android App 提供。</p>'+activeProblems.map((v,i)=>card(problemButtons(v,i)+`<p>${v.due?'已到期':'未到期'} · 阶段 ${v.stage} · ${date(v.due_at)}</p><button data-review="${i}" data-kind="reviewed">本次已完成</button><button data-review="${i}" data-kind="retry">明天再练</button><button data-review="${i}" data-kind="ignore">忽略</button>`)).join('')+(activeProblems.length?'':empty('暂无补题计划'));}
  if(page==='checkin'){const data=await request('/api/me/club/checkin');return '<h1>训练打卡</h1>'+card(`<p>${esc(data.day)} · 今日已同步 ${data.actual} AC</p><p>${data.checked_in?'已打卡':'尚未打卡'} · 连续 ${data.streak} 天</p><form id="checkin-form"><label>每日目标<input name="target" type="number" min="1" max="100" value="1" required></label><button>达到目标后打卡</button></form><p>本地通知请在 Android App 内设置；预览不模拟系统通知。</p>`);}
  if(page==='training'){let due;try{const data=rows(await request('/api/me/club/reviews')).filter(v=>v.due);due=data.length?data.map(v=>`<p>${esc(v.platform)} · ${esc(v.problem_id)}</p>`).join(''):empty('暂无到期补题');}catch(e){due=err(e);}return '<h1>今日训练</h1>'+card('<h2>今日到期补题</h2>'+due+btn('查看补题与间隔复习','reviews'))+'<form id="training-form"><label>训练平台<select id="platform"><option value="codeforces">Codeforces</option><option value="atcoder">AtCoder</option></select></label><label>中心难度<input name="difficulty" type="number" min="0" max="4000" value="1100" required></label><input name="tag" placeholder="标签、题名或题号"><button>生成相邻三档训练</button></form><div id="training-zones"></div>';}
  if(page==='contests')return '<h1>赛事复盘</h1><form id="contest-form"><input name="contest_id" placeholder="比赛 ID" required><button>查询</button></form><div id="contest-rows"></div>';
  throw Error('页面不存在');
}
function templateList(q){return LOCAL_TEMPLATES.map((v,i)=>[v,i]).filter(([v])=>(v.title+v.tags+v.notes).toLowerCase().includes(q.toLowerCase())).map(([v,i])=>`<button data-template="${i}">${esc(v.title)}</button>`).join('')||empty('没有匹配模板');}
function formDialog(title,fields,path,method,extra={}){dialog(title,'<form id="data-form">'+fields+'<button>提交</button><div id="form-error"></div></form>');document.getElementById('data-form').onsubmit=e=>{e.preventDefault();const data={...extra,...Object.fromEntries(new FormData(e.target))};if('tag'in data){data.tags=[data.tag];delete data.tag;}write(path,method,data,async result=>{popup.close();await show();dialog('操作结果',`<p>${esc(result.message||'已保存')}</p>`);});};}
function mistakeForm(item={}){formDialog('个人错因',`<select name="tag">${tags.map(t=>`<option ${item.tags?.includes(t)?'selected':''}>${t}</option>`).join('')}</select><textarea name="note" maxlength="2000">${esc(item.note||'')}</textarea>`,'/api/me/club/mistakes','PUT',state.problem);}
function bind(){
  const find=id=>document.getElementById(id);
  content.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>action(b.dataset.action));content.querySelectorAll('[data-post]').forEach(b=>b.onclick=()=>{state.post=Number(b.dataset.post);show('detail');});content.querySelectorAll('[data-problem-index]').forEach(b=>b.onclick=()=>{state.problem=activeProblems[Number(b.dataset.problemIndex)];state.topicQuery='';state.topicTag='';show('discussions');});
  content.querySelectorAll('[data-template]').forEach(b=>b.onclick=()=>{const item=LOCAL_TEMPLATES[Number(b.dataset.template)];dialog(item.title,`<p>${esc(item.notes)}</p>${reader('```'+item.language+'\n'+item.code+'\n```')}<button id="copy-template">复制</button>`);find('copy-template').onclick=async()=>{try{await navigator.clipboard.writeText(item.code);find('copy-template').textContent='已复制';}catch{find('copy-template').textContent='无法自动复制，请手动选择代码';}};});
  if(find('prev'))find('prev').onclick=()=>{state.number--;show();};if(find('next'))find('next').onclick=()=>{state.number++;show();};if(find('days'))find('days').onchange=e=>{state.days=e.target.value;state.number=1;show();};if(find('platform')&&state.page!=='training')find('platform').onchange=e=>{state.platform=e.target.value;state.number=1;show();};
  if(find('filter'))find('filter').onclick=async()=>{if(popup.open||opening)return;opening=true;try{const data=rows(await request('/api/forum/categories'));dialog('分类与排序','<form id="filters"><select name="category"><option value="">全部</option>'+data.map(v=>`<option value="${esc(v.slug)}">${esc(v.name)}</option>`).join('')+'</select><select name="sort"><option value="latest">最新</option><option value="hot">热门</option><option value="unanswered">待回答</option></select><button>应用</button></form>');find('filters').onsubmit=e=>{e.preventDefault();state.category=e.target.category.value;state.sort=e.target.sort.value;state.number=1;show('forum');};}catch(e){dialog('筛选不可用',err(e));}finally{opening=false;}};
  if(find('template-query'))find('template-query').oninput=e=>{find('template-list').innerHTML=templateList(e.target.value);bind();};
  if(find('compose')){const form=find('compose');form.oninput=()=>{localStorage.setItem(draftKey(),JSON.stringify(Object.fromEntries(new FormData(form))));find('draft-status').textContent='本地草稿已保存';};find('preview-body').onclick=()=>dialog('正文预览',reader(form.elements.body.value));form.onsubmit=e=>{e.preventDefault();const data=Object.fromEntries(new FormData(form));data.category_id=Number(data.category_id);write('/api/forum/posts','POST',data,async result=>{localStorage.removeItem(draftKey());await show('forum');dialog('提交结果',`<p>${esc(result.message)}</p>`);});};}
  if(find('login'))find('login').onsubmit=async e=>{e.preventDefault();if(writing)return;writing=true;const data=Object.fromEntries(new FormData(e.target));if(e.target.remember.checked)localStorage.setItem('acm_remembered_account',data.username);else localStorage.removeItem('acm_remembered_account');e.target.password.value='';content.innerHTML=empty('正在登录，等待服务端确认…');try{await request('/api/auth/login','POST',loginPayload(data.username,data.password));const session=await request('/api/auth/me');if(!session.authenticated||!session.csrf_token)throw Error('服务器未确认登录');state.csrf=session.csrf_token;state.account=session.qq_id||data.username;writing=false;await show('account');if(session.must_change_password)action('password');}catch(error){state.csrf='';writing=false;await show('account');dialog('登录失败',err(error));}finally{writing=false;}};
  if(find('topic-filter'))find('topic-filter').onsubmit=e=>{e.preventDefault();state.topicQuery=e.target.q.value;state.topicTag=e.target.tag.value;show();};
  content.querySelectorAll('[data-edit-mistake]').forEach(b=>b.onclick=()=>{state.problem=activeProblems[Number(b.dataset.editMistake)];mistakeForm(state.problem);});content.querySelectorAll('[data-remove-mistake]').forEach(b=>b.onclick=()=>{if(confirm('移出这道错题？'))write('/api/me/club/mistakes','DELETE',activeProblems[Number(b.dataset.removeMistake)],()=>show());});
  content.querySelectorAll('[data-review]').forEach(b=>b.onclick=()=>write('/api/me/club/reviews','PUT',{...activeProblems[Number(b.dataset.review)],action:b.dataset.kind},()=>show()));
  if(find('checkin-form'))find('checkin-form').onsubmit=e=>{e.preventDefault();write('/api/me/club/checkin','POST',{target:Number(e.target.elements.target.value)},()=>show());};
  if(find('comment'))find('comment').onsubmit=e=>{e.preventDefault();write('/api/forum/posts/'+state.post+'/comments','POST',{body:e.target.body.value,parent_id:0},()=>show());};
  content.querySelectorAll('[data-favorite]').forEach(b=>b.onclick=()=>{const row=activeProblems[Number(b.dataset.favorite)];write('/api/me/problems/'+encodeURIComponent(row.platform)+'/'+encodeURIComponent(row.problem_id)+'/state','PUT',{is_favorite:!row.is_favorite},()=>show());});
  content.querySelectorAll('[data-statement]').forEach(b=>b.onclick=async()=>{if(popup.open||opening)return;opening=true;try{const row=activeProblems[Number(b.dataset.statement)],data=await request('/api/me/problems/'+encodeURIComponent(row.platform)+'/'+encodeURIComponent(row.problem_id));dialog(data.problem_name||row.problem_id,reader(data.statement_text||data.statement_html||'题面尚未采集。')+rows(data.samples||[]).map(v=>`<pre>${esc(v.input)}</pre><pre>${esc(v.output)}</pre>`).join(''));}catch(e){dialog('题目加载失败',err(e));}finally{opening=false;}});
  if(find('training-form'))find('training-form').onsubmit=async e=>{e.preventDefault();if(writing)return;writing=true;const form=e.target,slot=find('training-zones'),platform=find('platform').value,base=Number(form.difficulty.value),min=platform==='codeforces'?800:0,max=platform==='codeforces'?3500:4000;slot.innerHTML='';try{if(!Number.isInteger(base)||base<min||base>max){slot.innerHTML=err(Error(`中心难度需为 ${min}–${max} 的整数`));return;}for(const [i,name] of ['稳定基础','主训练','突破上限'].entries())try{const difficulty=Math.max(min,Math.min(max,base+(i-1)*150)),data=await request('/api/me/challenge/start','POST',{platform,tag:form.tag.value,difficulty});slot.insertAdjacentHTML('beforeend',card(`<h3>${name} · 目标 ${difficulty}</h3><p>${esc(data.problem_name||data.problem_id)}</p><p>${esc(data.recommendation_reason)}</p>`));}catch(error){slot.insertAdjacentHTML('beforeend',err(error));}}finally{writing=false;}};
  if(find('contest-form'))find('contest-form').onsubmit=async e=>{e.preventDefault();const contest=e.target.contest_id.value;try{const data=rows(await request('/api/me/contest/reviews?contest_id='+encodeURIComponent(contest)));find('contest-rows').innerHTML=data.map((v,i)=>card(`<b>${esc(v.problem_id)}</b><select data-contest="${i}">${[['todo','未做'],['queued','待补题'],['solved','已解决'],['ignored','忽略']].map(([key,n])=>`<option value="${key}" ${String(v.status).replace('unsolved','queued').replace('reviewed','solved')===key?'selected':''}>${n}</option>`).join('')}</select>`)).join('')||empty('暂无比赛题目记录，请先同步');content.querySelectorAll('[data-contest]').forEach(b=>b.onchange=()=>write('/api/me/contest/reviews','PUT',{contest_id:contest,problem_id:data[Number(b.dataset.contest)].problem_id,status:b.value},async()=>{}));}catch(error){find('contest-rows').innerHTML=err(error);}};
}
async function action(name){if(writing||popup.open)return;if(['club','sheets','mistakes','reviews','templates','checkin','training','contests','account','mine','compose'].includes(name))return show(name);if(name==='retry')return show();if(name==='favorites'){state.favorite=!state.favorite;state.number=1;return show();}
  if(name==='logout'){writing=true;let failure;try{await request('/api/auth/logout','POST',{});}catch(e){failure=e;}finally{state.csrf='';state.profile=null;writing=false;await show('account');if(failure)dialog('已退出本机登录',`<p>服务端注销未确认：${esc(failure.message)}</p>`);}return;}
  if(name==='new-topic')return formDialog('按题讨论（Web 审核后公开）','<input name="title" minlength="4" maxlength="120" placeholder="标题" required><textarea name="body" minlength="5" maxlength="20000" required></textarea><select name="tag">'+tags.map(t=>`<option>${t}</option>`).join('')+'</select>','/api/club/problem-discussions','POST',state.problem);
  if(name==='add-mistake')return mistakeForm();if(name==='add-review')return write('/api/me/club/reviews','PUT',{...state.problem,action:'add'},async result=>dialog('计划更新',`<p>${esc(result.message)}</p>`));
  if(name==='like')return write('/api/forum/posts/'+state.post+'/like','POST',{},()=>show());if(name==='report')return formDialog('简单举报','<textarea name="reason" minlength="3" maxlength="500" required></textarea>','/api/forum/posts/'+state.post+'/report','POST');
  if(name==='password')return formDialog('修改密码','<label>当前密码<input name="old_password" type="password" required></label><label>新密码（12–128 位，至少三类字符）<input name="new_password" type="password" minlength="12" maxlength="128" required></label>','/api/auth/change-password','POST');if(name==='rename')return formDialog('修改昵称','<input name="name" maxlength="80" required>','/api/me/profile','PUT');
  if(name==='bindings')return dialog('OJ 绑定摘要（只读）',Object.entries(state.profile?.user||{}).filter(([k])=>['cf_handle','luogu_id','atcoder_handle','nowcoder_id','cjlu_username'].includes(k)).map(([k,v])=>`<p>${esc(k)}：${esc(v||'未绑定')}</p>`).join(''));
  if(name==='recent')try{const data=await request('/api/me/profile');return dialog('最近 AC · 仅本人可见',rows(data.recent_ac||[]).map(v=>`<p>${esc(v.problem_name||v.problem_id)} · ${esc(v.platform)} · ${date(v.submit_time)}</p>`).join('')||empty('暂无 AC 记录'));}catch(e){return dialog('读取失败',err(e));}
  if(name==='history'){dialog('历史记录',history().map((v,i)=>`<p>${esc(v)} <button data-delete-history="${i}">删除</button></p>`).join('')||empty('暂无历史'));popup.querySelectorAll('[data-delete-history]').forEach(b=>b.onclick=()=>{localStorage.setItem('acm_search_history',JSON.stringify(history().filter((_,i)=>i!==Number(b.dataset.deleteHistory))));popup.close();show('search');});}
  if(name==='history-settings'){dialog('历史记录设置',`<label><input id="record-history" type="checkbox" ${read('acm_record_search')!=='0'?'checked':''}>记录历史（仅本机）</label><button id="clear-history">清空</button>`);document.getElementById('record-history').onchange=e=>localStorage.setItem('acm_record_search',e.target.checked?'1':'0');document.getElementById('clear-history').onclick=()=>{localStorage.removeItem('acm_search_history');popup.close();show('search');};}
}
let searchScope='forum';document.getElementById('global-search').onfocus=()=>{if(['forum','rank','problems'].includes(state.page)){searchScope=state.page;show('search');}};document.getElementById('header-search').onsubmit=e=>{e.preventDefault();const term=document.getElementById('global-search').value.trim();if(!term)return;state.query=term;state.number=1;if(read('acm_record_search')!=='0')localStorage.setItem('acm_search_history',JSON.stringify([term,...history().filter(v=>v!==term)].slice(0,10)));show(searchScope);};document.addEventListener('click',e=>{const b=e.target.closest('[data-history]');if(b){document.getElementById('global-search').value=history()[Number(b.dataset.history)];document.getElementById('header-search').requestSubmit();}});
document.getElementById('avatar').onclick=()=>show('account');document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>{state.number=1;state.query='';show(b.dataset.page);});document.getElementById('close-popup').onclick=()=>{if(!writing)popup.close();};popup.addEventListener('cancel',e=>{if(writing)e.preventDefault();});document.getElementById('mode').textContent=offline?'v0.2.0 离线开发预览 · 不请求 API，不伪造数据':'v0.2.0 开发预览 · 连接受 CORS 与会话限制';show(new URLSearchParams(location.search).get('view')||'forum');
